import React from 'react';
import {
  Box,
  BoxAlignItems,
  BoxFlexDirection,
  FontWeight,
  Icon,
  IconColor,
  IconName,
  IconSize,
  Text,
  TextColor,
  TextVariant,
} from '@metamask/design-system-react';
import type { TokenTrustConfig } from '#shared/lib/token-search/types';
import { useI18nContext } from '../../../hooks/useI18nContext';

export type SecurityTrustTranslate = (
  key: string,
  substitutions?: string[],
) => string;

export const getSecurityTrustBadgeConfig = (
  resultType: string | undefined,
  t: SecurityTrustTranslate,
): TokenTrustConfig | null => {
  switch (resultType) {
    case 'Verified':
      return {
        icon: IconName.VerifiedFilled,
        iconColor: IconColor.InfoDefault,
        label: null,
        accessibleLabel: t('securityTrustVerified'),
      };
    case 'Warning':
    case 'Spam':
      return {
        icon: IconName.Danger,
        iconColor: IconColor.WarningDefault,
        alertSeverity: 'warning',
        label: t('securityTrustRisky'),
        backgroundColor: 'warning-muted',
        textColor: TextColor.WarningDefault,
      };
    case 'Malicious':
      return {
        icon: IconName.Danger,
        iconColor: IconColor.ErrorDefault,
        alertSeverity: 'danger',
        label: t('securityTrustMalicious'),
        backgroundColor: 'error-muted',
        textColor: TextColor.ErrorDefault,
      };
    default:
      return null;
  }
};

type SecurityTrustInlineBadgeProps = {
  badge: TokenTrustConfig;
  testId?: string;
  onClick?: () => void;
};

export const SecurityTrustInlineBadge = ({
  badge,
  testId,
  onClick,
}: SecurityTrustInlineBadgeProps) => {
  if (badge.label === null) {
    const verifiedIcon = (
      <Icon
        aria-label={badge.accessibleLabel}
        data-testid={onClick ? undefined : testId}
        name={badge.icon}
        size={IconSize.Sm}
        color={badge.iconColor}
        className="shrink-0"
      />
    );

    if (onClick) {
      return (
        <button
          type="button"
          onClick={onClick}
          data-testid={testId}
          aria-label={badge.accessibleLabel ?? testId ?? 'security-badge'}
          className="shrink-0 cursor-pointer border-0 bg-transparent p-0 leading-none"
        >
          {verifiedIcon}
        </button>
      );
    }

    return verifiedIcon;
  }

  const tagBackgroundClass =
    badge.backgroundColor === 'warning-muted'
      ? 'bg-warning-muted'
      : 'bg-error-muted';

  const tag = (
    <Box
      flexDirection={BoxFlexDirection.Row}
      alignItems={BoxAlignItems.Center}
      className={`inline-flex shrink-0 items-center gap-1 rounded-md px-2 py-0.5 ${tagBackgroundClass}`}
      data-testid={onClick ? undefined : testId}
    >
      <Icon name={badge.icon} size={IconSize.Sm} color={badge.iconColor} />
      <Text
        variant={TextVariant.BodyXs}
        color={badge.textColor}
        fontWeight={FontWeight.Medium}
      >
        {badge.label}
      </Text>
    </Box>
  );

  if (!onClick) {
    return tag;
  }

  return (
    <button
      type="button"
      onClick={onClick}
      data-testid={testId}
      className="shrink-0 cursor-pointer border-0 bg-transparent p-0"
    >
      {tag}
    </button>
  );
};

export const SecurityBadge = ({ value }: { value?: string }) => {
  const t = useI18nContext() as SecurityTrustTranslate;
  const badge = getSecurityTrustBadgeConfig(value, t);

  if (!badge) {
    return null;
  }

  return <SecurityTrustInlineBadge badge={badge} testId="security-badge" />;
};
